'use client';

import {
  Clipboard as ClipboardPrimitive,
  useClipboard,
  useClipboardContext,
} from '@ark-ui/react/clipboard';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { CheckIcon, CopyIcon } from '@/lib/moduix/icons/ui';
import styles from './Clipboard.module.css';

const Clipboard = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.Root>,
  ComponentProps<typeof ClipboardPrimitive.Root>
>(function Clipboard({ className, ...props }, ref) {
  return (
    <ClipboardPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="clipboard-root"
    />
  );
});

const ClipboardRootProvider = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.RootProvider>,
  ComponentProps<typeof ClipboardPrimitive.RootProvider>
>(function ClipboardRootProvider({ className, ...props }, ref) {
  return (
    <ClipboardPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="clipboard-root-provider"
    />
  );
});

const ClipboardLabel = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.Label>,
  ComponentProps<typeof ClipboardPrimitive.Label>
>(function ClipboardLabel({ className, ...props }, ref) {
  return (
    <ClipboardPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="clipboard-label"
    />
  );
});

const ClipboardControl = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.Control>,
  ComponentProps<typeof ClipboardPrimitive.Control>
>(function ClipboardControl({ className, ...props }, ref) {
  return (
    <ClipboardPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="clipboard-control"
    />
  );
});

const ClipboardInput = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.Input>,
  ComponentProps<typeof ClipboardPrimitive.Input>
>(function ClipboardInput({ asChild, className, ...props }, ref) {
  return (
    <ClipboardPrimitive.Input
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.input, className)}
      {...props}
      data-slot="clipboard-input"
    />
  );
});

const ClipboardTrigger = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.Trigger>,
  ComponentProps<typeof ClipboardPrimitive.Trigger>
>(function ClipboardTrigger({ asChild, className, ...props }, ref) {
  return (
    <ClipboardPrimitive.Trigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="clipboard-trigger"
    />
  );
});

const ClipboardIndicator = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.Indicator>,
  ComponentProps<typeof ClipboardPrimitive.Indicator>
>(function ClipboardIndicator({ className, children, copied, ...props }, ref) {
  return (
    <ClipboardPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      copied={copied ?? <CheckIcon />}
      {...props}
      data-slot="clipboard-indicator"
    >
      {children ?? <CopyIcon />}
    </ClipboardPrimitive.Indicator>
  );
});

const ClipboardValueText = forwardRef<
  ComponentRef<typeof ClipboardPrimitive.ValueText>,
  ComponentProps<typeof ClipboardPrimitive.ValueText>
>(function ClipboardValueText({ className, ...props }, ref) {
  return (
    <ClipboardPrimitive.ValueText
      ref={ref}
      className={clsx(styles.valueText, className)}
      {...props}
      data-slot="clipboard-value-text"
    />
  );
});

const ClipboardContext = ClipboardPrimitive.Context;

export {
  Clipboard,
  ClipboardContext,
  ClipboardControl,
  ClipboardIndicator,
  ClipboardInput,
  ClipboardLabel,
  ClipboardRootProvider,
  ClipboardTrigger,
  ClipboardValueText,
  useClipboard,
  useClipboardContext,
};

@layer moduix.components {
  .root {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-clipboard-gap, var(--moduix-spacing-1-5));
    width: 100%;
    color: var(--moduix-color-foreground);
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .control {
    display: flex;
    align-items: center;
    gap: var(--moduix-clipboard-control-gap, var(--moduix-spacing-2));
    width: 100%;
  }

  .input,
  .trigger {
    box-sizing: border-box;
    min-height: var(--moduix-clipboard-height, var(--moduix-size-md));
    margin: 0;
    border: var(--moduix-border-width-sm) solid
      var(--moduix-clipboard-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-clipboard-radius, var(--moduix-radius-md));
    color: var(--moduix-color-foreground);
    font: inherit;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .input {
    width: 100%;
    min-width: 0;
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3);
    background-color: var(--moduix-clipboard-input-bg, var(--moduix-color-background));
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: calc(var(--moduix-border-width-sm) * -1);

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }
  }

  .trigger {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    padding-inline: var(--moduix-spacing-4);
    background-color: var(--moduix-clipboard-trigger-bg, var(--moduix-color-background));
    appearance: none;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
    white-space: nowrap;
    cursor: pointer;

    & :where(svg) {
      width: var(--moduix-clipboard-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-clipboard-icon-size, var(--moduix-spacing-4));
      flex-shrink: 0;
    }

    @media (hover: hover) {
      &:hover:not(:disabled) {
        background-color: var(--moduix-clipboard-trigger-bg-hover, var(--moduix-color-accent));
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: calc(var(--moduix-border-width-sm) * -1);
    }

    &:active:not(:disabled) {
      opacity: 0.94;
    }
  }

  .indicator {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  .valueText {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}
